<?php require __DIR__.'/_layout.php';x1_require_role('operator');$db=x1_db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();$type=trim((string)$_POST['type']);$payload=json_decode((string)($_POST['payload']??'{}'),true);if(!is_array($payload))throw new RuntimeException('Payload must be JSON');x1_job_enqueue($type,$payload,(int)($_POST['priority']??100));header('Location:jobs.php');exit;}catch(Throwable $e){$msg=$e->getMessage();}}$rows=$db?x1_db_all('SELECT * FROM jobs ORDER BY created_at DESC LIMIT 500'):[];top(tr('Job Queue','Fila de Jobs'));?><section class="card hero"><div class=eyebrow>ASYNC OPERATIONS</div><h2><?=tr('Queue long-running work instead of blocking panel requests','Coloque trabalho demorado em fila em vez de bloquear pedidos do painel')?></h2></section><?php if($msg):?><section class="notice warn"><?=h($msg)?></section><?php endif?><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><div class=formgrid><label>Job Type<input name=type value="health_check" required></label><label>Priority<input type=number name=priority value=100></label><label>Payload JSON<textarea name=payload>{}</textarea></label></div><button><?=tr('Enqueue','Adicionar à fila')?></button></form></section><section class=section><table><tr><th>Created</th><th>Type</th><th>Status</th><th>Priority</th><th>Attempts</th><th>Run after</th><th>Error</th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['created_at'])?></td><td><?=h($x['type'])?></td><td><?=h($x['status'])?></td><td><?=h($x['priority'])?></td><td><?=h($x['attempts'])?> / <?=h($x['max_attempts'])?></td><td><?=h($x['run_after'])?></td><td><?=h($x['last_error'])?></td></tr><?php endforeach?></table></section><?php bottom();